// @registry editor-canvas@0.3.2
'use client';

import {
  Editor,
  useBlockActions,
  useCommand,
  useMoveTargets,
  useSelection,
} from '@createcms/react/editor';
import { Canvas } from '@createcms/react/editor/canvas';
import {
  ArrowDownIcon,
  ArrowUpIcon,
  CopyIcon,
  GripVerticalIcon,
  MoreHorizontalIcon,
  PlusIcon,
  Trash2Icon,
} from 'lucide-react';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Separator } from '@/components/ui/separator';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';

const ringMotion =
  'motion-safe:transition-[opacity] motion-safe:duration-(--editor-duration) motion-safe:ease-out motion-reduce:transition-none';

function Overlay({
  className,
  ...props
}: React.ComponentProps<typeof Canvas.Overlay>) {
  return (
    <Canvas.Overlay
      data-slot="editor-overlay"
      className={cn(className)}
      {...props}
    />
  );
}

function SelectionRing({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Canvas.SelectionRing>) {
  return (
    <Canvas.SelectionRing
      data-slot="editor-selection-ring"
      className={cn('border-editor-selection border', ringMotion, className)}
      {...props}
      render={(ringProps, state) => (
        <div {...ringProps}>
          {state.blockType ? (
            <span
              data-slot="editor-selection-chip"
              className="bg-editor-selection text-primary-foreground pointer-events-none absolute top-1.5 left-1.5 rounded-md px-1.5 py-0.5 text-[10px] leading-none font-medium"
            >
              {state.blockType}
            </span>
          ) : null}
          {children}
        </div>
      )}
    />
  );
}

function HoverRing({
  className,
  ...props
}: React.ComponentProps<typeof Canvas.HoverRing>) {
  return (
    <Canvas.HoverRing
      data-slot="editor-hover-ring"
      className={cn('border-editor-hover border', ringMotion, className)}
      {...props}
    />
  );
}

function FieldRing({
  className,
  ...props
}: React.ComponentProps<typeof Canvas.FieldRing>) {
  return (
    <Canvas.FieldRing
      data-slot="editor-field-ring"
      className={cn('border-editor-focus border', className)}
      {...props}
    />
  );
}

function CanvasIconButton({
  label,
  disabled,
  onClick,
  children,
}: {
  label: string;
  disabled?: boolean;
  onClick?: () => void;
  children: React.ReactNode;
}) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            type="button"
            variant="ghost"
            size="icon-xs"
            disabled={disabled}
            onClick={onClick}
            className="pointer-events-auto"
          />
        }
      >
        {children}
        <span className="sr-only">{label}</span>
      </TooltipTrigger>
      <TooltipContent side="top">{label}</TooltipContent>
    </Tooltip>
  );
}

function DefaultBlockToolbarActions() {
  const selected = useSelection().selected;
  const actions = useBlockActions(selected ?? '');
  if (!selected || actions.parent === null) return null;

  return (
    <>
      <DragHandle blockId={selected} />
      <Separator orientation="vertical" className="h-4" />
      <CanvasIconButton
        label="Move up"
        disabled={!actions.canMoveUp}
        onClick={() => actions.moveUp()}
      >
        <ArrowUpIcon />
      </CanvasIconButton>
      <CanvasIconButton
        label="Move down"
        disabled={!actions.canMoveDown}
        onClick={() => actions.moveDown()}
      >
        <ArrowDownIcon />
      </CanvasIconButton>
      <Separator orientation="vertical" className="h-4" />
      <CanvasIconButton label="Duplicate" onClick={() => actions.duplicate()}>
        <CopyIcon />
      </CanvasIconButton>
      <CanvasIconButton label="Delete" onClick={() => actions.remove()}>
        <Trash2Icon />
      </CanvasIconButton>
      <MoreActions blockId={selected} />
      <Editor.Slot name="block-toolbar" props={{ blockId: selected }} />
      <Canvas.InlineRichTextToolbar>
        <Separator orientation="vertical" className="h-4" />
        <Editor.RichTextToolbar className="flex items-center gap-0.5">
          {RICH_TEXT_FORMATS.map((format) => (
            <Editor.RichTextToolbarButton
              key={format.mark}
              mark={format.mark}
              aria-label={format.label}
              title={format.label}
              className={cn(
                'hover:bg-accent aria-pressed:bg-accent pointer-events-auto inline-flex size-7 items-center justify-center rounded-sm text-xs disabled:hidden',
                format.className,
              )}
            >
              {format.text}
            </Editor.RichTextToolbarButton>
          ))}
        </Editor.RichTextToolbar>
      </Canvas.InlineRichTextToolbar>
    </>
  );
}

function CommandMenuItem({ id }: { id: string }) {
  const command = useCommand(id);
  if (!command) return null;
  return (
    <DropdownMenuItem
      className="pointer-coarse:min-h-11"
      disabled={!command.canExecute}
      onClick={() => command.run()}
    >
      {command.label ?? id}
      {command.shortcutLabel ? (
        <DropdownMenuShortcut>{command.shortcutLabel}</DropdownMenuShortcut>
      ) : null}
    </DropdownMenuItem>
  );
}

/** The structure actions that do not fit the toolbar, reachable without a drag. */
function MoreActions({ blockId }: { blockId: string }) {
  const { targets, moveTo } = useMoveTargets(blockId);
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type="button"
            variant="ghost"
            size="icon-xs"
            className="pointer-events-auto"
          />
        }
      >
        <MoreHorizontalIcon />
        <span className="sr-only">More actions</span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-48">
        <DropdownMenuSub>
          <DropdownMenuSubTrigger
            className="pointer-coarse:min-h-11"
            disabled={targets.length === 0}
          >
            Move to…
          </DropdownMenuSubTrigger>
          <DropdownMenuSubContent className="max-h-72 overflow-y-auto">
            {targets.map((target) => (
              <DropdownMenuItem
                key={`${target.parent.id}:${target.parent.slot}`}
                className="pointer-coarse:min-h-11"
                style={{ paddingLeft: 8 + target.depth * 12 }}
                onClick={() => moveTo(target.parent, target.count)}
              >
                {target.label}
              </DropdownMenuItem>
            ))}
          </DropdownMenuSubContent>
        </DropdownMenuSub>
        <CommandMenuItem id="block.wrap" />
        <CommandMenuItem id="clipboard.copy" />
        <CommandMenuItem id="selection.parent" />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/** Formats the block toolbar offers while a rich text field is edited in place. */
const RICH_TEXT_FORMATS = [
  { mark: 'bold', label: 'Bold', text: 'B', className: 'font-bold' },
  { mark: 'italic', label: 'Italic', text: 'I', className: 'italic' },
  { mark: 'underline', label: 'Underline', text: 'U', className: 'underline' },
  {
    mark: 'strike',
    label: 'Strikethrough',
    text: 'S',
    className: 'line-through',
  },
] as const;

function BlockToolbar({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Canvas.BlockToolbar>) {
  return (
    <Canvas.BlockToolbar
      data-slot="editor-block-toolbar"
      className={cn(
        'bg-background border-border flex items-center gap-0.5 rounded-md border p-0.5 shadow-sm',
        'motion-safe:animate-in motion-safe:fade-in-0 motion-safe:zoom-in-95 motion-safe:duration-150 motion-reduce:animate-none',
        className,
      )}
      {...props}
    >
      {children ?? <DefaultBlockToolbarActions />}
    </Canvas.BlockToolbar>
  );
}

function InsertButton({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Canvas.InsertButton>) {
  return (
    <Canvas.InsertButton
      data-slot="editor-insert-button"
      className={cn(
        'bg-background border-border pointer-events-auto flex size-6 items-center justify-center rounded-full border shadow-sm',
        className,
      )}
      {...props}
    >
      {children ?? (
        <>
          <PlusIcon className="size-3" />
          <span className="sr-only">Insert block</span>
        </>
      )}
    </Canvas.InsertButton>
  );
}

function DropIndicator({
  className,
  ...props
}: React.ComponentProps<typeof Canvas.DropIndicator>) {
  return (
    <Canvas.DropIndicator
      data-slot="editor-drop-indicator"
      className={cn(
        'data-[variant=line]:bg-editor-drop data-[variant=line]:h-0.5 data-[variant=line]:rounded-full',
        'data-[variant=box]:border-editor-drop data-[variant=box]:bg-editor-drop/10 data-[variant=box]:rounded-md data-[variant=box]:border-2',
        'motion-safe:data-[variant=line]:animate-in motion-safe:data-[variant=line]:fade-in-0 motion-safe:data-[variant=line]:zoom-in-95 motion-safe:data-[variant=line]:duration-150 motion-reduce:animate-none',
        className,
      )}
      {...props}
    />
  );
}

function InlineText({
  className,
  ...props
}: React.ComponentProps<typeof Canvas.InlineText>) {
  return (
    <Canvas.InlineText
      data-slot="editor-inline-text"
      className={cn(className)}
      {...props}
    />
  );
}

function DragHandle({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Canvas.DragHandle>) {
  return (
    <Canvas.DragHandle
      data-slot="editor-drag-handle"
      className={cn(
        'bg-background border-border pointer-events-auto flex size-6 cursor-grab items-center justify-center rounded border select-none active:cursor-grabbing',
        className,
      )}
      {...props}
    >
      {children ?? (
        <>
          <GripVerticalIcon className="size-3.5" />
          <span className="sr-only">Drag to move</span>
        </>
      )}
    </Canvas.DragHandle>
  );
}

function PaletteItem({
  className,
  ...props
}: React.ComponentProps<typeof Canvas.PaletteItem>) {
  return (
    <Canvas.PaletteItem
      data-slot="editor-palette-item"
      className={cn(
        'hover:bg-sidebar-accent hover:text-sidebar-accent-foreground flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm disabled:opacity-50',
        className,
      )}
      {...props}
    />
  );
}

function DragPreview({
  className,
  ...props
}: React.ComponentProps<typeof Canvas.DragPreview>) {
  return (
    <Canvas.DragPreview
      data-slot="editor-drag-preview"
      className={cn(
        'bg-background border-border rounded-md border px-2 py-1 text-sm shadow-md',
        'motion-safe:animate-in motion-safe:fade-in-0 motion-safe:zoom-in-95 motion-safe:duration-150 motion-reduce:animate-none',
        className,
      )}
      {...props}
    />
  );
}

export {
  BlockToolbar,
  DragHandle,
  DragPreview,
  DropIndicator,
  FieldRing,
  HoverRing,
  InlineText,
  InsertButton,
  Overlay,
  PaletteItem,
  SelectionRing,
};

/* @registry editor-canvas@0.3.2 */
/*
 * Opt-in for an inline canvas (no frame): sticky and fixed elements would
 * pin to the editor window, and a backdrop filter would trap fixed
 * descendants, so `editor-canvas-static` lays them out in flow. A frame
 * surface needs none of this.
 */
[data-editor-canvas].editor-canvas-static .sticky,
[data-editor-canvas].editor-canvas-static .fixed {
  position: static;
}

[data-editor-canvas].editor-canvas-static {
  backdrop-filter: none;
}

[data-editor-canvas][data-dragging] {
  user-select: none;
}

/* Empty slots stay a reachable drop target while editing. */
[data-editor-canvas][data-interactive='edit'] [data-editor-slot]:empty {
  min-height: var(--editor-slot-min-empty-height, 128px);
}

/* One end mark at the start of the line, 4 px past the gap. */
[data-slot='editor-drop-indicator'][data-variant='line']::before {
  content: '';
  position: absolute;
  width: var(--editor-drop-mark, 8px);
  height: var(--editor-drop-mark, 8px);
  border: 2px solid var(--editor-drop);
  border-radius: 999px;
  background: var(--background, #fff);
  box-sizing: border-box;
}

[data-slot='editor-drop-indicator'][data-variant='line'][data-orientation='horizontal']::before {
  top: 50%;
  left: -4px;
  transform: translateY(-50%);
}

[data-slot='editor-drop-indicator'][data-variant='line'][data-orientation='vertical']::before {
  left: 50%;
  top: -4px;
  transform: translateX(-50%);
}

/* The container a drag drops into. */
[data-editor-drop-target-ring][data-nested] {
  border-radius: 4px;
  background: color-mix(in oklab, var(--editor-drop) 8%, transparent);
  animation: editor-drop-target var(--editor-duration-slow, 250ms)
    cubic-bezier(0.15, 1, 0.3, 1);
}

@keyframes editor-drop-target {
  from {
    background: transparent;
  }
}

/* The dragged block stays in place, dimmed. */
[data-editor-canvas] [data-editor-block][data-dragging] {
  opacity: 0.4;
}

/* Dropped blocks flash once. */
[data-editor-canvas] [data-editor-block][data-dropped] {
  animation: editor-dropped 700ms cubic-bezier(0.25, 0.1, 0.25, 1);
}

@keyframes editor-dropped {
  from {
    background-color: color-mix(in oklab, var(--editor-drop) 20%, transparent);
  }
}

/* Rings follow their block exactly: no transition on position or size,
   only on opacity when chrome appears. */
[data-slot='editor-selection-ring'],
[data-slot='editor-hover-ring'] {
  transition-property: opacity;
  transition-duration: var(--editor-duration, 150ms);
  transition-timing-function: ease-out;
  border-radius: var(--el-radius, 0);
}

[data-slot='editor-hover-ring'] {
  box-shadow:
    inset 0 0 0 1px var(--editor-hover, var(--editor-drop)),
    0 0 0 1px rgb(255 255 255 / 0.7);
}

[data-slot='editor-selection-ring'] {
  box-shadow:
    inset 0 0 0 2px var(--editor-selection, var(--editor-drop)),
    0 0 0 1px rgb(255 255 255 / 0.7);
}

/* A cut-off edge draws no line. */
[data-slot='editor-selection-ring'][data-clamped-top],
[data-slot='editor-hover-ring'][data-clamped-top] {
  border-top-left-radius: 0;
  border-top-right-radius: 0;
}

[data-slot='editor-block-toolbar'][data-scrolling] {
  opacity: 0;
}

[data-box='padding'] {
  background: rgb(147 196 125 / 0.55);
}

[data-box='margin'] {
  background: rgb(246 178 107 / 0.66);
}

[data-editor-empty-slot][data-drag-over] {
  outline: 2px dashed var(--editor-drop);
  outline-offset: -2px;
}

/* Empty blocks stay visible and hittable while editing. */
[data-editor-canvas][data-interactive='edit'] [data-editor-block]:empty {
  min-height: 24px;
  outline: 1px dashed rgb(0 0 0 / 0.7);
  outline-offset: -1px;
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.7);
}

@media (prefers-reduced-motion: reduce) {
  [data-slot='editor-selection-ring'],
  [data-slot='editor-hover-ring'],
  [data-slot='editor-drop-indicator'],
  [data-slot='editor-block-toolbar'],
  [data-editor-drop-target-ring],
  [data-editor-canvas] [data-editor-block][data-dropped] {
    animation: none !important;
    transition: none !important;
  }
}

/*
 * Target sizes (WCAG 2.5.8): overlay buttons are at least 24 px; drag
 * handles get a 44 px hit area around their icon, and every primary
 * control grows to 44 px under a coarse pointer.
 */
[data-slot='editor-drag-handle'] {
  position: relative;
}

[data-slot='editor-drag-handle']::after {
  content: '';
  position: absolute;
  inset: -10px;
}

@media (pointer: coarse) {
  [data-slot='editor-drag-handle'],
  [data-slot='editor-insert-button'],
  [data-slot='editor-block-toolbar'] button {
    min-width: 44px;
    min-height: 44px;
  }
}
